import React, { useRef } from 'react';

import { formatDate } from '@dynatrace-sdk/units';

import { calendarFieldCSS } from './Calendar.sty.js';
import { CalendarItem } from './CalendarItem.js';
import { useMonth } from './hooks/useMonth.js';
import { _useFormFieldContext } from '../../forms-core/hooks/useFormFieldContext.js';

export const Month = ({ date }: { date: Date }) => {
  // Reference of the month button, needed to pass to the hook for proper focus management
  const itemRef = useRef<HTMLDivElement>(null);

  const { ariaLabel, tabIndex, isSelected, isCurrent, onClick } = useMonth({
    date,
    itemRef,
  });
  const { disabled } = _useFormFieldContext();
  const highlightColor = isSelected ? 'primary' : 'neutral';

  return (
    <td
      className={calendarFieldCSS({
        color: highlightColor,
        isDisabled: disabled,
      })}
      role="presentation"
    >
      <CalendarItem
        data-testid="calendar-month-body-button"
        ref={itemRef}
        className="calendar-button calendar-body-button"
        isCurrent={isCurrent}
        isSelected={isSelected}
        isDisabled={disabled}
        highlightColor={highlightColor}
        tabIndex={tabIndex}
        role="gridcell"
        aria-selected={!!isSelected}
        ariaLabel={ariaLabel}
        view="month"
        onClick={onClick}
      >
        {formatDate(date, { month: 'short' })}
      </CalendarItem>
    </td>
  );
};
Month['displayName'] = 'Month';
